insert into public.hadith_families(slug,title,family_type,scope,narrative_group_id,verification_status,created_by,method) values ('farewell-pilgrimage-sanctity','Farewell Pilgrimage Sermon: "Your Blood and Your Wealth Are Sacred"','event','Reports of the Farewell Pilgrimage sermon(s) containing "your blood and wealth (and honour) are sacred to you like the sanctity of this day of yours". Multiple companions (Abū Bakra, Ibn ʿAbbās, Ibn ʿUmar, Jābir, ʿAmr b. al-Aḥwaṣ, Abū Saʿīd). Jābir’s long ḥajj narrative is complementary (one sermon element among many). Which day (ʿArafa vs. the Day of Sacrifice at Minā) is reported differently: a candidate harmonisation is that the theme was repeated, not a contradiction.',null,'source_checked','grok-bot','hce-rules-v1') on conflict (slug) do nothing;
