insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='farewell-pilgrimage-sanctity'),'conclusion',1,'Twenty-two indexed records from six companions report the Farewell Pilgrimage declaration that "your blood and your wealth are sacred to you like the sanctity of this day of yours": Abū Bakra (10), Ibn ʿUmar (4), Jābir (3), ʿAmr b. al-Aḥwaṣ (3), Ibn ʿAbbās (1) and Abū Saʿīd (1). This is genuinely multi-companion attestation.',array['bukhari:67','bukhari:1742','muslim:1218','tirmidhi:2159','bukhari:1739','ibnmajah:3931']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='farewell-pilgrimage-sanctity'),'conclusion',2,'Within the Abū Bakra branch, every chain passes through Muḥammad b. Sīrīn (candidate common link). Below him it spreads through Ayyūb, Ibn ʿAwn and Qurra b. Khālid, and above him through ʿAbd al-Raḥmān b. Abī Bakra and, on some routes, Ḥumayd b. ʿAbd al-Raḥmān.',array['bukhari:67','bukhari:4406','bukhari:1741','muslim:1679d','bukhari:7078']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='farewell-pilgrimage-sanctity'),'conclusion',3,'The day is named differently. The Day of Sacrifice (yawm al-naḥr) appears in the Abū Bakra, Ibn ʿAbbās and Ibn ʿUmar reports; Bukhārī 6043 says only "at Minā"; the ʿAmr b. al-Aḥwaṣ reports answer "the Day of the Greater Ḥajj" (yawm al-ḥajj al-akbar); and Jābir’s long ḥajj narrative places the sermon at ʿArafa. The engine keeps these as lexical values, not exclusive claims. A candidate reading is that the theme was repeated in more than one sermon (ʿArafa and the Day of Sacrifice), so it is not marked a contradiction.',array['bukhari:1739','bukhari:6043','tirmidhi:2159','muslim:1218']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='farewell-pilgrimage-sanctity'),'conclusion',4,'Elements differ mostly by omission or complement. "Honour" (aʿrāḍ) is added in most routes, but not in Jābir’s. "Time has come round as on the day of creation" appears only in the Ayyūb ← Ibn Sīrīn routes of Abū Bakra. Abolition of Jāhiliyya usury and blood-claims, and counsel about women, appear in Jābir and ʿAmr b. al-Aḥwaṣ.',array['bukhari:4406','muslim:1679a','muslim:1218','ibnmajah:3055','tirmidhi:3087']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='farewell-pilgrimage-sanctity'),'conclusion',5,'Jābir’s report (Muslim 1218, Abū Dāwūd 1905, Ibn Mājah 3074) is one long ḥajj narrative transmitted by Ḥātim b. Ismāʿīl ← Jaʿfar b. Muḥammad ← his father. The sermon is one element in it, so it is complementary to the short sermon reports.',array['muslim:1218','abudawud:1905','ibnmajah:3074']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='farewell-pilgrimage-sanctity'),'uncertainty',1,'Several short forms (Bishr, Ayyūb, Muḥammad = Ibn Sīrīn, Yaḥyā = al-Qaṭṭān, Abū al-Aḥwaṣ) are proposed identifications, not source-checked.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='farewell-pilgrimage-sanctity'),'uncertainty',2,'Muḥammad b. ʿAbd Allāh, Bukhārī’s teacher in 6785, is left unidentified.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='farewell-pilgrimage-sanctity'),'uncertainty',3,'Other sermon reports that do not use the phrase كحرمة يومكم هذا (e.g. other wordings of "do not revert after me to disbelief") are not yet included.','grok-bot') on conflict do nothing;
